+.ov { position: absolute; inset: 0; padding: 13px; display: flex; flex-direction: column; justify-content: space-between; background: linear-gradient(to bottom, rgba(0,0,0,.48), transparent 34%, rgba(0,0,0,.68)); color: #fff; opacity: 0; transition: opacity .22s; pointer-events: none; }
 .tile:hover .ov, .tile:focus-within .ov { opacity: 1; }
+.ov a, .ov button { pointer-events: auto; }
